function paintIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[el.dataset.icon]||icons.info}</svg>`;});}paintIcons();
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const views={connect:['连接机台','开始新一次采集','先确认连接，再把每一次结果记录清楚。'],rules:['规则档案','让规则成为可复用的档案','提取、核对、保存，下一次不用重新开始。'],verify:['首转核验','先验证这一转，再记录下一百转','完整奖励链和最终审计通过后，机台才算准备好。'],capture:['实时采集','专注这一批，看清每一个结果','只展示真实记录；没有数据时，保留清楚的空状态。']};
function changeView(name){if(!views[name])return;$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));$$('.nav-item').forEach(v=>{v.classList.toggle('active',v.dataset.view===name);if(v.dataset.view===name)v.setAttribute('aria-current','page');else v.removeAttribute('aria-current');});$$('[data-step]').forEach(v=>v.classList.toggle('current',v.dataset.step===name));$('#breadcrumb-page').textContent=views[name][0];$('#page-title').textContent=views[name][1];$('#page-subtitle').textContent=views[name][2];location.hash=name;}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>changeView(b.dataset.view)));$$('[data-go]').forEach(b=>b.addEventListener('click',()=>changeView(b.dataset.go)));if(location.hash)changeView(location.hash.slice(1));
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3800);}
function updateState(){const value=$('#preview-state').value;const ready=value==='ready';$('#connection-badge').classList.toggle('ready',ready);$('#connection-badge').innerHTML=`<span></span>${ready?'已连接 · 预览':value==='idle'?'尚未连接':'连接未就绪'}`;$('#device-state').textContent=value==='idle'?'等待检测':'示例设备';$('#game-state').textContent=value==='idle'?'等待识别':'示例前台应用';$('#heartbeat-state').textContent=ready?'双向匹配':value==='idle'?'尚未验证':'未就绪';const messages={changed:'连接在检测期间发生了变化。请保持目标机台打开，重新检测。',missing:'尚未匹配到游戏心跳。请等待游戏加载完成后重新检测。'};const notice=$('#connection-notice');notice.hidden=!messages[value];notice.textContent=messages[value]||'';$('#detect').querySelector('span').textContent=ready?'重新检测连接':'自动检测并连接';}
$('#preview-state').addEventListener('change',updateState);$('#detect').addEventListener('click',()=>{toast('这是视觉交互稿，不会连接设备。可用上方“状态预览”切换成功与失败状态。');});$('#diffusion').addEventListener('click',()=>{const off=document.body.classList.toggle('no-diffusion');$('#diffusion').textContent=`弥散背景：${off?'关':'开'}`;$('#diffusion').setAttribute('aria-pressed',String(!off));});
$('#rules-confirmed').addEventListener('change',e=>$('#save-rules').disabled=!e.target.checked);$('#save-rules').addEventListener('click',()=>toast('设计稿中的保存只演示反馈，不会改动真实档案。'));$('#spin-count').addEventListener('input',e=>{const count=Number(e.target.value);$('#target-label').textContent=count>0?count:'—';const ticks=$$('.chart-axis span');ticks[1].textContent=count>0?`第 ${Math.ceil(count/2)} 次`:'—';ticks[2].textContent=count>0?`第 ${count} 次`:'—';});
for(const id of ['verify-start','capture-start'])$('#'+id).addEventListener('click',()=>toast('此处仅预览操作入口，不会监听、旋转或发送游戏请求。'));
for(const id of ['history','settings','export'])$('#'+id).addEventListener('click',()=>toast('当前为视觉稿，该入口将在正式界面接入现有功能。'));
for(const el of $$('.table-action'))el.addEventListener('click',()=>toast('正式界面将在这里打开当前Symbol的编辑面板。'));
for(const id of ['add-symbol','add-feature','new-machine'])$('#'+id).addEventListener('click',()=>toast('新增入口预览；不会修改本地机台档案。'));
$('#manage-machines').addEventListener('click',()=>$('#archive-dialog').showModal());$('#archive-delete').addEventListener('click',()=>{toast('真实界面删除前会确认名称，保留历史数据并支持撤销。');});
const imported=[];const dialog=$('#image-dialog');function openImport(){dialog.showModal();$('#drop-zone').focus();}for(const id of ['open-import','import-main'])$('#'+id).addEventListener('click',openImport);$('#pick-files').addEventListener('click',()=>$('#file-input').click());
async function addFiles(files){let errors=0,duplicates=0;for(const file of files){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>20*1024*1024){errors++;continue;}const bytes=await file.arrayBuffer();const sum=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');if(imported.some(x=>x.sum===sum)){duplicates++;continue;}if(imported.length>=12){errors++;continue;}imported.push({file,sum,url:URL.createObjectURL(file)});}renderImages();$('#import-hint').textContent=`当前 ${imported.length} 张${duplicates?`，跳过 ${duplicates} 张重复图片`:''}${errors?`，${errors} 张不符合格式、大小或数量限制`:''}。只保存在当前设计稿页面，不会发送。`;}
function renderImages(){const grid=$('#image-grid');grid.replaceChildren();imported.forEach((item,i)=>{const tile=document.createElement('div');tile.className='image-tile';const img=document.createElement('img');img.src=item.url;img.alt=`规则截图 ${i+1}`;const name=document.createElement('span');name.textContent=item.file.name||`粘贴截图 ${i+1}`;const remove=document.createElement('button');remove.setAttribute('aria-label',`移除第${i+1}张截图`);remove.textContent='×';remove.onclick=()=>{URL.revokeObjectURL(imported[i].url);imported.splice(i,1);renderImages();};tile.append(img,name,remove);grid.append(tile);});$('#use-images').innerHTML=`使用这 ${imported.length} 张截图<i data-icon="arrow-right"></i>`;paintIcons($('#use-images'));}
$('#file-input').addEventListener('change',e=>addFiles(e.target.files));const zone=$('#drop-zone');zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('drag-over');});zone.addEventListener('dragleave',()=>zone.classList.remove('drag-over'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('drag-over');addFiles(e.dataTransfer.files);});document.addEventListener('paste',e=>{if(!dialog.open)return;const images=[...e.clipboardData.items].filter(i=>i.kind==='file').map(i=>i.getAsFile()).filter(Boolean);if(images.length){e.preventDefault();addFiles(images);}});$('#clear-images').addEventListener('click',()=>{imported.forEach(i=>URL.revokeObjectURL(i.url));imported.length=0;renderImages();$('#import-hint').textContent='列表已清空，可继续拖入或粘贴。';});$('#use-images').addEventListener('click',()=>{$('#attachment-summary').hidden=!imported.length;$('#attachment-summary').textContent=`已添加 ${imported.length} 张截图 · 本地预览`;$('#ai-generate').disabled=!imported.length;dialog.close();});$('#ai-generate').addEventListener('click',()=>toast('截图已在预览中。这份设计稿不调用模型，也不会消耗额度。'));
